import type { ITranslationAdapter, PluginConfig } from './base.ts';

const EXACT_PATTERNS: Record<string, string> = {
  'list files in current directory': '列出当前目录文件',
  'show working tree status': '查看 Git 工作区状态',
  'check git status': '查看 Git 状态',
  'check working tree status': '查看工作区状态',
  'check workspace structure': '检查工作区目录结构',
  'list plugins': '列出插件列表',
  'run build': '执行项目构建',
  'run tests': '运行测试',
  'run linter': '代码风格检查',
  'typecheck project': 'TypeScript 类型检查',
};

const PREFIX_PATTERNS: Array<[RegExp, (match: RegExpExecArray) => string]> = [
  [/^locate\s+(.+)$/i, (m) => `定位 ${m[1]}`],
  [/^inspect\s+(.+)$/i, (m) => `检查 ${m[1]}`],
  [/^explore\s+(.+)$/i, (m) => `浏览 ${m[1]}`],
  [/^read\s+file\s*(.*)$/i, (m) => `读取文件 ${m[1]}`.trim()],
  [/^read\s+(.+)$/i, (m) => `读取 ${m[1]}`],
  [/^write\s+file\s*(.*)$/i, (m) => `写入文件 ${m[1]}`.trim()],
  [/^write\s+(.+)$/i, (m) => `写入 ${m[1]}`],
  [/^edit\s+file\s*(.*)$/i, (m) => `编辑文件 ${m[1]}`.trim()],
  [/^edit\s+(.+)$/i, (m) => `编辑 ${m[1]}`],
  [/^create\s+file\s*(.*)$/i, (m) => `创建文件 ${m[1]}`.trim()],
  [/^create\s+(.+)$/i, (m) => `创建 ${m[1]}`],
  [/^delete\s+file\s*(.*)$/i, (m) => `删除文件 ${m[1]}`.trim()],
  [/^delete\s+(.+)$/i, (m) => `删除 ${m[1]}`],
  [/^search\s+files?\s*(.*)$/i, (m) => `搜索文件 ${m[1]}`.trim()],
  [/^search\s+(.+)$/i, (m) => `搜索 ${m[1]}`],
  [/^find\s+files?\s*(.*)$/i, (m) => `查找文件 ${m[1]}`.trim()],
  [/^find\s+(.+)$/i, (m) => `查找 ${m[1]}`],
  [/^grep\s+(.+)$/i, (m) => `检索文本 ${m[1]}`],
  [/^check\s+(.+)$/i, (m) => `检查 ${m[1]}`],
  [/^run\s+command:\s*(.+)$/i, (m) => `运行命令: ${m[1]}`],
  [/^run\s+(.+)$/i, (m) => `运行 ${m[1]}`],
  [/^execute\s+(.+)$/i, (m) => `执行 ${m[1]}`],
  [/^install\s+(.+)$/i, (m) => `安装 ${m[1]}`],
  [/^build\s+(.+)$/i, (m) => `构建 ${m[1]}`],
  [/^verify\s+(.+)$/i, (m) => `验证 ${m[1]}`],
  [/^stage\s+(.+)$/i, (m) => `暂存 ${m[1]}`],
  [/^commit\s+(.+)$/i, (m) => `提交 ${m[1]}`],
  [/^list\s+(.+)$/i, (m) => `列出 ${m[1]}`],
  [/^clean\s+(.+)$/i, (m) => `清理 ${m[1]}`],
  [/^update\s+(.+)$/i, (m) => `更新 ${m[1]}`],
  [/^fetch\s+(.+)$/i, (m) => `获取 ${m[1]}`],
];

export class BuiltinDictAdapter implements ITranslationAdapter {
  readonly id = 'builtin';
  readonly name = '离线技术词典';

  isAvailable(_config: PluginConfig): boolean {
    return true;
  }

  async translate(text: string, _signal: AbortSignal, _config: PluginConfig): Promise<string> {
    const raw = text.trim();
    const lower = raw.toLowerCase();

    // 1. Exact match
    if (EXACT_PATTERNS[lower]) {
      return EXACT_PATTERNS[lower];
    }

    // 2. Prefix pattern match
    for (const [pattern, formatter] of PREFIX_PATTERNS) {
      const match = pattern.exec(raw);
      if (match) {
        return formatter(match);
      }
    }

    return raw;
  }
}
